entry.content:
题意给定一个序列，求这个序列所有的循环移位中的 最大值。 思路发现题解区还没有基于势能分析法的做法，发一个。 推式子题。对于一个序列 而言。 它的一个循环移位 $A{t} = A{k + 1}, A_{k + 2}, \dots, A_n, A_1, \dots, A_k，对于1 \le i \le n - k$，有：
\text{mex} ([{A_{t}}_1, {A_t}_2, \dots, {A_t}_i]) = \min (\text{mex} ([A_1, A_2, \dots, A_{i + k}]), \min \limits_{1 \le j \le k} A_j)而对于 ，我们发现多余的部分到了前面，所以：
\text{mex} ([{A_t}_1, {A_t}_2, \dots, {A_t}_i]) = \min (\text{mex} ([A_1, A_2, \dots, A_n]), \min \limits_{i + k - n + 1 \le j \le k} A_j)上述答案可以尝试使用数据结构维护。但是，我们发现线段树没有方法直接求区间取 、区间求和。但是，如果我们尝试分析暴力区间修改的时间复杂度，会发现：如果我们记录区间最大值、次大值、最大值的个数以及区间和，如果当前需要取 的数 ，那么无需操作；如果 ，那么这个区间就有 个数需要取 ；否则直接递归操作。这样，时间复杂度为 ，其中 为操作次数。 注意：不能使用 set 求初始答案，这样会超时。可以利用排列的性质， 地求。 #include &lt;bits/stdc++.h&gt;using namespace std;using ll = long long;const int MAXN = 1e6 + 10, INF = 2e9;int n, a[MAXN], ans[MAXN];struct Node { ll sum, mx, cmx, cnt;};struct Tag { int val; bool operator==(const Tag &amp;oth) const { return val == oth.val; }};struct SegTree { Node dat[MAXN &lt;&lt; 2], E = {0, 0, 0, 0}; Tag tag[MAXN &lt;&lt; 2], I = {INF}; Node comb(const Node &amp;dat1, const Node &amp;dat2) { Node res = E; res.sum = dat1.sum + dat2.sum; if (dat1.mx &gt; dat2.mx) { res.mx = dat1.mx; res.cmx = max(dat2.mx, dat1.cmx); res.cnt = dat1.cnt; } else if (dat1.mx &lt; dat2.mx) { res.mx = dat2.mx; res.cmx = max(dat1.mx, dat2.cmx); res.cnt = dat2.cnt; } else { res.mx = dat1.mx; res.cmx = max(dat1.cmx, dat2.cmx); res.cnt = dat1.cnt + dat2.cnt; } return res; } Tag F(const Tag &amp;tag1, const Tag &amp;tag2) { return {min(tag1.val, tag2.val)}; } Node f(const Node &amp;dat, const Tag &amp;tag) { if (dat.mx &lt;= tag.val) return dat; return {dat.sum + (tag.val - dat.mx) * dat.cnt, tag.val, dat.cmx, dat.cnt}; } void down(int root) { if (tag[root] == I) return; tag[root &lt;&lt; 1] = F(tag[root &lt;&lt; 1], tag[root]); tag[root &lt;&lt; 1 | 1] = F(tag[root &lt;&lt; 1 | 1], tag[root]); dat[root &lt;&lt; 1] = f(dat[root &lt;&lt; 1], tag[root]); dat[root &lt;&lt; 1 | 1] = f(dat[root &lt;&lt; 1 | 1], tag[root]); tag[root] = I; } void build(int root, int l, int r, bool f) { tag[root] = I; if (l == r) { if (f) { dat[root] = {INF, INF, -1, 1}; } else { dat[root] = {ans[l], ans[l], -1, 1}; } return; } int mid = l + r &gt;&gt; 1; build(root &lt;&lt; 1, l, mid, f); build(root &lt;&lt; 1 | 1, mid + 1, r, f); dat[root] = comb(dat[root &lt;&lt; 1], dat[root &lt;&lt; 1 | 1]); } void modify(int root, int l, int r, int L, int R, Tag t) { if (L &gt; R || dat[root].mx &lt;= t.val) return; if (L &lt;= l &amp;&amp; R &gt;= r &amp;&amp; dat[root].cmx &lt; t.val) { dat[root] = f(dat[root], t); tag[root] = F(tag[root], t); return; } down(root); int mid = l + r &gt;&gt; 1; if (L &lt;= mid) modify(root &lt;&lt; 1, l, mid, L, R, t); if (R &gt; mid) modify(root &lt;&lt; 1 | 1, mid + 1, r, L, R, t); dat[root] = comb(dat[root &lt;&lt; 1], dat[root &lt;&lt; 1 | 1]); } Node query(int root, int l, int r, int L, int R) { if (L &lt;= l &amp;&amp; R &gt;= r) return dat[root]; if (L &gt; r || R &lt; l) return E; down(root); int mid = l + r &gt;&gt; 1; return comb(query(root &lt;&lt; 1, l, mid, L, R), query(root &lt;&lt; 1 | 1, mid + 1, r, L, R)); }} T1, T2;void Solve() { cin &gt;&gt; n; for (int i = 1; i &lt;= n; i++) { cin &gt;&gt; a[i]; } int mi = INF; ans[n] = n; for (int i = n - 1; i &gt;= 1; i--) { mi = min(mi, a[i + 1]); ans[i] = mi; } T1.build(1, 1, n, 0); T2.build(1, 1, n, 1); ll res = T1.query(1, 1, n, 1, n).sum; mi = INF; for (int i = 1; i &lt; n; i++) { T1.modify(1, 1, n, i + 1, n, {a[i]}); if (i == 1) { T2.modify(1, 1, n, i, i, {n}); } else { T2.modify(1, 1, n, 2, i, {a[i]}); } res = max(res, T1.query(1, 1, n, i + 1, n).sum + T2.query(1, 1, n, 1, i).sum); } cout &lt;&lt; res &lt;&lt; '\n';}int main() { ios::sync_with_stdio(0), cin.tie(0); int T; for (cin &gt;&gt; T; T--; Solve()); return 0;}
